	startDynasty: (teamId) => {
		if (get().starting) return;
		const school = TEAM_BY_ID[teamId];
		if (!school) return;
		const mode = get().selectMode;
		if (mode === "career" && !careerEligible(school)) {
			set({ toast: `Career starts at rating 62 and under.` });
			return;
		}
		const named = get().draftCoach;
		if (!named.first.trim() || !named.last.trim()) {
			set({
				view: "create",
				toast: "First and last name are required.",
				starting: false,
				busy: null
			});
			return;
		}
		const gen = ++bootGen;
		set({
			starting: true,
			busy: "Loading",
			selectedTeamId: teamId,
			toast: null
		});
		afterPaint(() => {
			(async () => {
				if (bootGen !== gen) return;
				try {
					await ensureDefaultNames();
					if (bootGen !== gen) return;
					const d = get().draftCoach;
					const identity = {
						first: d.first.trim() || "Coach",
						last: d.last.trim() || "Stone",
						age: Math.max(28, Math.min(64, d.age || 38)),
						almaMaterId: d.almaMaterId && TEAM_BY_ID[d.almaMaterId] ? d.almaMaterId : null
					};
					const state = patchSettings(newDynasty(teamId, readChallengeSeed() || (Date.now() ^ Math.random() * 1e9) >>> 0, {
						careerMode: mode === "career",
						identity,
						eraDecade: mode === "eras" ? get().eraDecade : null
					}), { difficulty: get().draftDifficulty });
					if (bootGen !== gen) return;
					const tuto = tutorialDone() ? "hub" : "tutorial";
					rememberView(tuto, true);
					set({
						starting: false,
						busy: null,
						state,
						view: tuto,
						feedback: {
							title: `${identityName(identity)} at ${school.name}`,
							detail: identity.almaMaterId ? `${TEAM_BY_ID[identity.almaMaterId]?.name} is still home. That job will reach further later.` : "No alma mater on the file.",
							parts: [{
								label: "Rating",
								delta: school.prestige
							}]
						}
					});
					afterPaint(() => {
						try {
							persist(state);
						} catch (e) {
							console.error(e);
						}
					});
				} catch (e) {
					console.error(e);
					if (bootGen !== gen) return;
					set({
						starting: false,
						busy: null,
						toast: "Couldn't start that job."
					});
				}
			})();
		});
	},
