	saveNow: (name) => {
		const s = get().state;
		if (!s) {
			set({ toast: "Nothing to save yet." });
			return;
		}
		persistQueued = s;
		flushPersist();
		const label = name?.trim();
		if (!label) {
			if (!writeSave(s)) {
				set({
					toast: "Couldn't write the save. Delete an old file and try again.",
					saves: listSaves()
				});
				return;
			}
			set({
				saves: listSaves(),
				toast: null,
				feedback: {
					title: "Saved",
					detail: `Season ${s.season} is on this device.`,
					parts: [{
						label: "Saves",
						delta: 1
					}]
				}
			});
			return;
		}
		const res = saveNamed(s, label);
		if (!res.ok) {
			set({
				toast: res.error ?? "Couldn't save.",
				saves: listSaves()
			});
			return;
		}
		set({
			saves: listSaves(),
			toast: null,
			feedback: {
				title: "Saved",
				detail: `Wrote “${label}”.`,
				parts: [{
					label: "Saves",
					delta: 1
				}]
			}
		});
	},
