	runPlay: () => {
		const s = get().state;
		if (!s) return;
		try {
			apply(get, set, runLivePossession(s), { view: "game" });
		} catch (e) {
			failPlay(set, e, "That possession didn't run.");
		}
	},
	runCall: (side, id) => {
		const s0 = get().state;
		if (!s0) return;
		try {
			apply(get, set, runLivePossession(setLiveCall(s0.liveGame && !s0.liveGame.planned ? lockGamePlan(s0) : s0, side, id)), { view: "game" });
		} catch (e) {
			failPlay(set, e, "That call didn't run.");
		}
	},
	runLate: (choice) => {
		const s0 = get().state;
		if (!s0) return;
		try {
			apply(get, set, runLivePossession(queueLate(s0.liveGame && !s0.liveGame.planned ? lockGamePlan(s0) : s0, choice)), { view: "game" });
		} catch (e) {
			failPlay(set, e, "That call didn't run.");
		}
	},
	forceEndgame: () => {
		let s = get().state;
		if (!s) return;
		try {
			if (!s.liveGame || s.liveGame.done) {
				const started = beginLiveGame(s);
				if (!started?.liveGame) {
					set({ toast: "No game to force. Tip one off first." });
					return;
				}
				s = lockGamePlan(started);
			} else if (!s.liveGame.planned) s = lockGamePlan(s);
			if (!s?.liveGame) return;
			apply(get, set, forceEndgameState(s), { view: "game" });
		} catch (e) {
			failPlay(set, e, "Couldn't set that finish.");
		}
	},
	forceTwoFor: () => {
		let s = get().state;
		if (!s) return;
		try {
			if (!s.liveGame || s.liveGame.done) {
				const started = beginLiveGame(s);
				if (!started?.liveGame) {
					set({ toast: "No game to force. Tip one off first." });
					return;
				}
				s = lockGamePlan(started);
			} else if (!s.liveGame.planned) s = lockGamePlan(s);
			if (!s?.liveGame) return;
			apply(get, set, forceTwoForState(s), { view: "game" });
		} catch (e) {
			failPlay(set, e, "Couldn't set the 2-for-1.");
		}
	},
