function burnerTease(state) {
	const land = carouselLand(state);
	const top = land.openings[0]?.school ?? land.hot[0];
	if (top) return {
		head: `${top.name} is in trouble`,
		note: `${top.coach} · ${top.record} · Trilly's posting`
	};
	const jump = land.jump[0];
	if (jump) return {
		head: `${jump.school.coach} is getting looks`,
		note: `${jump.school.name} · Trilly's posting`
	};
	if (portalOpen(state)) return {
		head: `${portalOf(state).transfers.filter((t) => !t.committedTo).length} names in the portal`,
		note: "Trilly's posting"
	};
	return {
		head: "Trilly's in the server",
		note: "carousel, portal rumors, the usual"
	};
}
function orderReplies(msgs) {
	const byId = new Map(msgs.map((m) => [m.id, m]));
	for (const m of msgs) {
		if (!m.replyTo) continue;
		const parent = byId.get(m.replyTo);
		if (parent && m.minutesAgo >= parent.minutesAgo) m.minutesAgo = Math.max(1, parent.minutesAgo - 1);
	}
	return msgs;
}
function burnerFeed(state) {
	const rng = rngFor(state, "feed");
	const land = carouselLand(state);
	const talkers = talkersOf(rng);
	const era = eraPortal(state.eraDecade);
	const channels = [
		{
			id: "carousel",
			label: "carousel",
			topic: "jobs, hot seats, who should get hired. Trilly posts. y'all react."
		},
		{
			id: "portal",
			label: era === "none" ? "transfers" : "portal",
			topic: era === "none" ? "guys changing schools still sit a year. talk like it." : "visits, who's leaving, who actually has a job. if Trilly didn't post it, it didn't happen."
		},
		{
			id: "lounge",
			label: "lounge",
			topic: "the games. keep the scoops in the other rooms."
		}
	];
	const messages = orderReplies([
		...buildCarousel(state, land, rng, talkers),
		...buildPortal(state, rng, talkers),
		...buildLounge(state, land, rng, talkers)
	]);
	return {
		server: "The Burner",
		members: 640 + state.seed % 280,
		online: 38 + (state.week * 7 + state.seed % 40) % 52,
		channels,
		users: USERS,
		messages,
		tease: burnerTease(state).head
	};
}
